SELECT p.memory_id::text,p.revision,r.body,paradedb.score(p.memory_id) FROM agenteam_memory.projections p JOIN agenteam_memory.memories m ON (m.project_id,m.agent_id,m.memory_id,m.current_revision)=(p.project_id,p.agent_id,p.memory_id,p.revision) JOIN agenteam_memory.revisions r ON (r.project_id,r.agent_id,r.memory_id,r.revision)=(p.project_id,p.agent_id,p.memory_id,p.revision) WHERE p.project_id=$1 AND p.agent_id=$2 AND p.generation_id=$3 AND m.status='active' AND r.status='active' AND (p.memory_id @@@ paradedb.match('index_text',$4,conjunction_mode=>false)) AND (cardinality($5::text[])=0 OR r.type=ANY($5)) AND r.tags @> $6::text[] ORDER BY paradedb.score(p.memory_id) DESC,p.memory_id LIMIT $7;
